using System;using System.Collections.Generic;using System.Text.Json;using Evaluator;using Observatory.Framework.Files.Journal;class Program{static void Main(){var cases=new List<object>();foreach(int first in new[]{0,1000000,1000000000})foreach(int next in new[]{0,1000000,1000000000}){Evaluator.Evaluator.EvalSettings=new StubSettings{MinimumValueForWorthMapping=first};var b=new Body(new Scan{BodyName="Oracle 1",PlanetClass="Earthlike body",MassEM=1},true,new BodyExtra());var initial=b.Extra.IsHighValue;Evaluator.Evaluator.EvalSettings.MinimumValueForWorthMapping=next;var afterSettings=b.Extra.IsHighValue;b.UpdateValues();cases.Add(new{first,next,initial,afterSettings,afterUpdate=b.Extra.IsHighValue});}Console.Write(JsonSerializer.Serialize(cases));}}